head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25004";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25004.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goDsclInsert
 * @description go Dscl Insert 처리
 * @param {String} formKorNm formKorNm
 * @returns {void}
 * @hidden N
 */
scwin.goDsclInsert = function (formKorNm) {
    (document.disclosureForm || { elements: [] }).formKorNm.value = formKorNm;
    /* 수동 전환 필요: 폼 disclosureForm 제출 — action 미보유 */ document.disclosureForm.submit();
};
